@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f4eee8;--muted:#8a8e9b;--red:#ff4e5e;--gold:#ffcc78;--line:#303441;--bg:#10131c}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#10131c;color:var(--ink);font-family:'Space Grotesk',sans-serif}body{display:flex;justify-content:center;align-items:center;min-height:100svh;padding:25px;background:radial-gradient(ellipse at 50% 45%,#202231 0,#10131c 65%)}.shell{width:min(100%,1080px)}.topbar{height:54px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:700;letter-spacing:.13em;color:var(--ink);text-decoration:none}.brand-mark{font-size:21px;color:var(--red);text-shadow:0 0 15px #ff4e5e77}.slash,.intro-card h1 span{color:var(--red)}.top-note,.sound-btn,.bottom-bar,.shell footer,.mini-controls,.eyebrow{font-family:'DM Mono',monospace}.top-note{font-size:10px;letter-spacing:.13em;color:#a8a9b5}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#81d69e;margin-right:8px;box-shadow:0 0 8px #81d69e}.sound-btn{background:transparent;color:#c5c6cf;border:1px solid var(--line);border-radius:4px;padding:8px 11px;font-size:11px;cursor:pointer}.sound-btn span{font-size:9px;letter-spacing:.08em;margin-left:4px}.game-frame{border:1px solid #383b48;background:#151822;box-shadow:0 22px 70px #0008,0 0 0 6px #ffffff04;overflow:hidden;border-radius:6px}.screen-wrap{position:relative;width:100%;aspect-ratio:16/9;background:#171b28;overflow:hidden}.screen-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}.scanlines{pointer-events:none;position:absolute;inset:0;z-index:2;opacity:.1;background:repeating-linear-gradient(0deg,transparent 0 3px,#000 4px 5px);mix-blend-mode:multiply}.overlay{position:absolute;inset:0;z-index:3;display:grid;place-items:center;background:linear-gradient(90deg,#10131cbb,#10131c3b 80%),linear-gradient(0deg,#111522bb,transparent 55%);transition:opacity .4s,visibility .4s}.overlay.hidden{opacity:0;visibility:hidden}.intro-card{width:53%;margin-left:42%;text-align:center;transform:translateY(-2px)}.eyebrow{font-size:8px;letter-spacing:.2em;color:#c4c0c5;display:flex;align-items:center;justify-content:center;gap:8px}.eyebrow-line{height:1px;width:19px;background:#ff4e5e}.intro-card h1{font-size:clamp(39px,7vw,72px);line-height:.77;letter-spacing:-.08em;margin:13px 0 14px;font-weight:700;text-shadow:4px 4px 0 #14151e}.intro-card h1 span{font-size:.55em;letter-spacing:-.1em}.story{font-size:11px;color:#c2c1ca;line-height:1.55;margin:0 auto 13px}.heart-row{display:flex;align-items:center;justify-content:center;gap:9px;margin:0 auto 15px}.heart{font-size:14px}.human{color:#ff5968;text-shadow:0 0 9px #ff5968aa}.lost{color:#565562;filter:grayscale(1);opacity:.55}.heart-row i{font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#a9a8b2;margin-left:4px}.start-btn{border:0;border-radius:3px;background:var(--red);color:#1b1017;font:700 11px 'DM Mono',monospace;letter-spacing:.1em;padding:12px 19px;cursor:pointer;box-shadow:0 5px 0 #a42d43;transition:transform .12s,filter .12s}.start-btn:hover{filter:brightness(1.13);transform:translateY(-1px)}.start-btn:active{transform:translateY(3px);box-shadow:0 2px 0 #a42d43}.start-btn span{font-size:9px;margin-left:15px}.mini-controls{margin-top:17px;font-size:8px;letter-spacing:.07em;color:#858794}.mini-controls kbd,.controls-hint span{display:inline-block;border:1px solid #4b4d59;border-radius:2px;padding:2px 4px;color:#ddd;margin:0 2px;font:9px 'DM Mono',monospace}.bottom-bar{height:61px;padding:0 21px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #303441;background:#171a24}.location{display:flex;align-items:center;gap:10px;min-width:215px}.location-icon{font-size:20px;color:var(--red)}.location b{display:block;font-size:10px;letter-spacing:.12em}.location small{display:block;color:#8b8d99;font-size:8px;margin-top:3px;letter-spacing:.05em}.progress{display:flex;align-items:center;gap:8px;color:#a5a5b0;font-size:9px}.progress-track{height:3px;width:105px;background:#3c3e49;border-radius:4px;overflow:hidden}.progress-track i{height:100%;width:0;display:block;background:var(--red);transition:width .4s}.controls-hint{color:#9395a0;font-size:8px;letter-spacing:.06em}.controls-hint span{color:#e8e5e5;margin-left:6px}footer{display:flex;align-items:center;justify-content:space-between;color:#686b77;font-size:8px;letter-spacing:.08em;padding:13px 2px}footer b{color:var(--red);font-size:11px}.mobile-controls{display:none}.mobile-group{display:flex;gap:8px}.mobile-controls button{width:52px;height:48px;color:#f5eee8;background:#202431dd;border:1px solid #525564;border-radius:8px;font-size:20px;touch-action:none;box-shadow:0 3px 0 #0b0d13}.mobile-controls button:active,.mobile-controls button.pressed{background:#ff4e5e;color:#15151b}.actions button:first-child{color:#ffcc78}
@media(max-width:650px){body{padding:10px 8px 108px;align-items:flex-start}.topbar{height:37px;margin-bottom:8px}.brand{font-size:12px}.brand-mark{font-size:17px}.top-note{font-size:7px}.sound-btn{padding:6px 7px}.sound-btn span{display:none}.game-frame{border-radius:4px}.bottom-bar{height:auto;min-height:55px;padding:8px 10px}.location{min-width:0;gap:6px}.location b{font-size:8px}.location small{font-size:6px}.location-icon{font-size:17px}.progress{gap:4px;font-size:7px}.progress-track{width:48px}.controls-hint{display:none}.shell footer{font-size:6px;gap:7px}.intro-card{width:58%;margin-left:39%}.eyebrow{font-size:6px}.story{font-size:8px;margin-bottom:8px}.heart-row{margin-bottom:9px;gap:5px}.heart{font-size:11px}.heart-row i{font-size:6px}.start-btn{font-size:8px;padding:8px 11px}.start-btn span{margin-left:7px}.mini-controls{font-size:6px;margin-top:10px}.mobile-controls{position:fixed;z-index:5;left:0;right:0;bottom:15px;display:flex;justify-content:space-between;padding:0 15px;pointer-events:none}.mobile-group{pointer-events:auto}.mobile-controls button{width:48px;height:48px}}
@media(max-height:500px) and (min-width:651px){body{padding:10px}.topbar{height:34px;margin-bottom:6px}.bottom-bar{height:47px}footer{padding:7px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const W = 480, H = 270, GROUND = 232;
  const overlay = document.getElementById('overlay');
  const startBtn = document.getElementById('startBtn');
  const stageName = document.getElementById('stageName');
  const stageSub = document.getElementById('stageSub');
  const progressText = document.getElementById('progressText');
  const progressFill = document.getElementById('progressFill');
  const stages = [
    { name:'NIGHT MARKET', sub:'DISTRICT 01 — THE OUTSKIRTS', sky:'#25213a', far:'#39304d', near:'#251f35', accent:'#ed9a65', boss:'THE WALL', type:'wall', heart:'SYMBIOTE HEART', color:'#b96be5' },
    { name:'REDLINE YARD', sub:'DISTRICT 02 — THE IRON QUARTER', sky:'#362436', far:'#533342', near:'#29212f', accent:'#ff795c', boss:'RAZOR HOUND', type:'hound', heart:'WOLF HEART', color:'#ffbb55' },
    { name:'BLACK VEIL HQ', sub:'DISTRICT 03 — THE DEAD CENTER', sky:'#171d30', far:'#263148', near:'#1b2131', accent:'#e45b75', boss:'THE KINGPIN', type:'king', heart:'YOUR HUMAN HEART', color:'#ff4e5e' }
  ];
  const platforms = [[{x:340,y:194,w:74},{x:610,y:176,w:92},{x:885,y:194,w:68},{x:1110,y:178,w:100}], [{x:300,y:190,w:100},{x:540,y:172,w:80},{x:810,y:194,w:80},{x:1085,y:174,w:92}], [{x:330,y:190,w:90},{x:570,y:171,w:94},{x:840,y:190,w:72},{x:1080,y:170,w:105}]];
  const levelLength = 1420;
  const key = {left:false,right:false,jump:false,attack:false,power:false};
  let state='title', stage=0, camera=0, last=0, time=0, sound=true, audio=null;
  let player, enemies=[], boss, shots=[], particles=[], pickups=[], shake=0, message='', messageTimer=0, transitionTimer=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const rand=(a,b)=>a+Math.random()*(b-a);
  function beginStage(index) {
    stage=index; camera=0; shots=[]; particles=[];
    const starts=[[470,760,1030],[420,690,995],[460,760,1060]][stage];
    enemies=starts.map((x,i)=>({x,y:GROUND-18,w:17,h:18,hp:2,dir:i%2?1:-1,base:x,dead:false,hit:0,kind:(i===1?'thrower':'punk')}));
    boss={x:levelLength-125,y:GROUND-40,w:34,h:40,hp:stage===2?10:8,max:stage===2?10:8,dir:-1,attack:1.6,hit:0,dead:false,phase:0};
    player={x:48,y:GROUND-30,w:16,h:30,vx:0,vy:0,face:1,hp:3,maxHp:3,onGround:true,attack:0,cooldown:0,power:0,invuln:0,dead:false,anim:0,checkpoint:50};
    pickups=[]; state='play'; message=stage===0?'THE MARKET NEVER SLEEPS':stage===1?'FOLLOW THE RED LIGHTS':'THE KING IS WAITING'; messageTimer=2.2;
    stageName.textContent=stages[stage].name; stageSub.textContent=stages[stage].sub; progressText.textContent=`0${stage+1}`; progressFill.style.width=`${stage*33.33}%`;
    overlay.classList.add('hidden');
  }
  function startGame(){beginStage(0);playTone(360,.08,'sine',.04);}
  startBtn.addEventListener('click',startGame);
  document.getElementById('soundBtn').addEventListener('click',e=>{sound=!sound;e.currentTarget.innerHTML=`♫ <span>SOUND ${sound?'ON':'OFF'}</span>`;if(sound)playTone(520,.08);});
  function playTone(freq,duration=.08,wave='square',volume=.025){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=wave;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch(_){}}
  function setKey(name,value){if(name in key)key[name]=value;}
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','w','a','s','d','j','k','enter'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')setKey('left',true);if(k==='d'||k==='arrowright')setKey('right',true);if(k==='w'||k==='arrowup'||k===' ')setKey('jump',true);if(k==='j'||k==='z')setKey('attack',true);if(k==='k'||k==='x')setKey('power',true);if(k==='enter'&&state==='title')startGame();if(k==='enter'&&(state==='win'||state==='dead'))startGame();});
  window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')setKey('left',false);if(k==='d'||k==='arrowright')setKey('right',false);if(k==='w'||k==='arrowup'||k===' ')setKey('jump',false);if(k==='j'||k==='z')setKey('attack',false);if(k==='k'||k==='x')setKey('power',false);});
  document.querySelectorAll('.mobile-controls button').forEach(button=>{const n=button.dataset.key;const down=e=>{e.preventDefault();button.classList.add('pressed');setKey(n,true);if(n==='attack')playerAttack();if(n==='power')usePower();};const up=e=>{e.preventDefault();button.classList.remove('pressed');setKey(n,false);};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);});
  function playerAttack(){if(state!=='play'||player.cooldown>0)return;player.attack=.18;player.cooldown=.3;playTone(155,.07,'sawtooth',.035);const reach=player.power>0?52:32;const ax=player.x+player.w/2+player.face*reach*.52;for(const e of enemies){if(!e.dead&&Math.abs(e.x+e.w/2-ax)<reach&&Math.abs(e.y-player.y)<34){e.hp--;e.hit=.16;if(e.hp<=0){e.dead=true;burst(e.x+8,e.y+8,'#ffb26b',10);playTone(230,.13,'square',.04);}}}if(boss&&!boss.dead&&Math.abs(boss.x+boss.w/2-ax)<reach+8&&Math.abs(boss.y-player.y)<48){boss.hp--;boss.hit=.18;shake=3;burst(boss.x+boss.w/2,boss.y+15,stages[stage].color,8);playTone(100,.1,'sawtooth',.045);if(boss.hp<=0)defeatBoss();}}
  function usePower(){if(state!=='play'||player.power<=0)return;player.power=0;if(stage===0){player.attack=.35;for(const e of enemies){if(!e.dead&&Math.abs(e.x-player.x)<83){e.hp-=3;e.hit=.2;if(e.hp<=0)e.dead=true;burst(e.x+8,e.y+8,'#d58bff',12);}}if(boss&&!boss.dead&&Math.abs(boss.x-player.x)<95){boss.hp-=2;boss.hit=.3;shake=5;burst(boss.x+15,boss.y+18,'#d58bff',15);if(boss.hp<=0)defeatBoss();}playTone(520,.2,'sawtooth',.05);}else{player.vx=player.face*9;player.invuln=.38;player.attack=.32;const radius=stage===1?70:82;for(const e of enemies){if(!e.dead&&Math.abs(e.x-player.x)<radius){e.hp-=3;if(e.hp<=0)e.dead=true;burst(e.x+8,e.y+8,stage===1?'#ffc565':'#ff5267',11);}}if(boss&&!boss.dead&&Math.abs(boss.x-player.x)<radius){boss.hp-=2;boss.hit=.3;shake=5;burst(boss.x+16,boss.y+18,stages[stage].color,13);if(boss.hp<=0)defeatBoss();}playTone(270,.22,'square',.05);}}
  function defeatBoss(){if(!boss||boss.dead)return;boss.dead=true;shots=[];shake=8;burst(boss.x+boss.w/2,boss.y+20,stages[stage].color,28);playTone(440,.18,'square',.06);setTimeout(()=>playTone(660,.24,'square',.05),100);message=stage<2?`${stages[stage].heart} RESTORED`:'ALL THREE HEARTS ARE YOURS';messageTimer=3.5;pickups.push({x:boss.x+8,y:GROUND-22,heart:true,age:0});transitionTimer=3.4;state='clear';}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-2.8,2.8),vy:rand(-3.2,1.3),life:rand(.24,.65),max:.65,color,size:Math.random()<.5?2:3});}
  function hurt(){if(player.invuln>0||state!=='play')return;player.hp--;player.invuln=1.15;player.vy=-4;player.vx=-player.face*2;shake=4;playTone(90,.2,'sawtooth',.05);burst(player.x+8,player.y+13,'#ff5267',8);if(player.hp<=0){state='dead';message='YOUR HEART STILL BEATS';messageTimer=2.4;setTimeout(()=>{if(state==='dead'){overlay.classList.remove('hidden');document.querySelector('.intro-card h1').innerHTML='TRY<br><span>AGAIN</span>';document.querySelector('.story').innerHTML='The Black Veil is still out there.<br>Your hunt is not over.';startBtn.innerHTML='RALLY & RETURN <span>▶</span>';setMobileMenu(true);}},1800);}}
  function setMobileMenu(show){document.querySelector('.mobile-controls').style.opacity=show?'0':'1';}
  function update(dt){time+=dt;if(messageTimer>0)messageTimer-=dt;particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx;p.y+=p.vy;p.vy+=.12;});if(shake>0)shake=Math.max(0,shake-dt*18);
    if(state==='clear'){transitionTimer-=dt;if(transitionTimer<=0){if(stage<2){beginStage(stage+1);player.power=1;player.hp=3;player.maxHp=3;}else{state='win';overlay.classList.remove('hidden');document.querySelector('.intro-card h1').innerHTML='HEARTS<br><span>RECLAIMED</span>';document.querySelector('.story').innerHTML='Three hearts. One city saved.<br>The Black Veil has fallen.';startBtn.innerHTML='PLAY AGAIN <span>▶</span>';setMobileMenu(true);} }return;}
    if(state!=='play')return;
    player.anim+=dt*(Math.abs(player.vx)>.3?12:4);player.cooldown=Math.max(0,player.cooldown-dt);player.attack=Math.max(0,player.attack-dt);player.invuln=Math.max(0,player.invuln-dt);player.power=player.power;
    if(key.left){player.vx-=23*dt;player.face=-1;}if(key.right){player.vx+=23*dt;player.face=1;}player.vx*=Math.pow(player.onGround?.78:.93,dt*60);player.vx=clamp(player.vx,-3.4,3.4);
    if(key.jump&&player.onGround){player.vy=-7.1;player.onGround=false;playTone(300,.06,'square',.018);}player.vy=Math.min(8,player.vy+.36);const oldY=player.y;player.x=clamp(player.x+player.vx,0,levelLength-20);player.y+=player.vy;player.onGround=false;
    if(player.y+player.h>=GROUND){player.y=GROUND-player.h;player.vy=0;player.onGround=true;}
    for(const p of platforms[stage]){if(player.vy>=0&&oldY+player.h<=p.y+2&&player.y+player.h>=p.y&&player.x+player.w>p.x&&player.x<p.x+p.w){player.y=p.y-player.h;player.vy=0;player.onGround=true;}}
    camera=clamp(player.x-160,0,levelLength-W+30);
    enemies.forEach(e=>{if(e.dead)return;e.hit=Math.max(0,e.hit-dt);e.x+=e.dir*(e.kind==='thrower'?13:19)*dt;if(Math.abs(e.x-e.base)>53)e.dir*=-1;if(Math.abs(player.x-e.x)<17&&Math.abs(player.y-e.y)<22)hurt();if(e.kind==='thrower'&&Math.random()<dt*.22)shots.push({x:e.x,y:e.y+5,vx:player.x>e.x?-.1:1,vy:0,enemy:true});});
    if(boss&&!boss.dead){boss.hit=Math.max(0,boss.hit-dt);boss.phase+=dt;const dist=player.x-boss.x;if(Math.abs(dist)>66)boss.x+=Math.sign(dist)*Math.min(1.05,Math.abs(dist)*.018);boss.dir=dist>0?1:-1;boss.attack-=dt;if(boss.attack<=0){boss.attack=boss.type==='wall'?1.5:boss.type==='hound'?1.15:1.0;boss.phase=0;if(boss.type==='wall'){for(let i=0;i<3;i++)shots.push({x:boss.x,y:GROUND-9,vx:-2.3-i*.55,vy:0,enemy:true,wide:true});}else if(boss.type==='hound'){boss.vx=-boss.dir*4.3;shots.push({x:boss.x+boss.w/2,y:boss.y+12,vx:-boss.dir*2.7,vy:-.6,enemy:true});}else{for(let i=-1;i<=1;i++)shots.push({x:boss.x,y:boss.y+16,vx:-2.7,vy:i*.8,enemy:true});}}if(boss.type==='hound'&&boss.vx){boss.x+=boss.vx;boss.vx*=.93;if(Math.abs(player.x-boss.x)<27&&Math.abs(player.y-boss.y)<37)hurt();}if(Math.abs(player.x-boss.x)<31&&Math.abs(player.y-boss.y)<38)hurt();}
    shots=shots.filter(s=>s.x>-25&&s.x<levelLength+20);shots.forEach(s=>{s.x+=s.vx;s.y+=s.vy;if(Math.abs(s.x-player.x-8)<12&&Math.abs(s.y-player.y-14)<15){hurt();s.x=-100;}});
    pickups.forEach(p=>{p.age+=dt;if(Math.abs(p.x-player.x-8)<18&&Math.abs(p.y-(player.y+15))<22){p.got=true;}});pickups=pickups.filter(p=>!p.got);
    if(key.attack){playerAttack();key.attack=false;}if(key.power){usePower();key.power=false;}
  }

  function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
  function text(str,x,y,size,color='#fff',align='left'){ctx.fillStyle=color;ctx.font=`${size}px monospace`;ctx.textAlign=align;ctx.fillText(str,Math.round(x),Math.round(y));ctx.textAlign='left';}
  function drawBackground(){const s=stages[stage]||stages[0];rect(0,0,W,H,s.sky);const gradient=ctx.createLinearGradient(0,0,0,H);gradient.addColorStop(0,'#1c2030');gradient.addColorStop(1,s.sky);ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);
    // moon and distant block skyline
    rect(355,30,30,30,'#f0a77a');rect(360,25,30,30,s.sky);rect(0,148,W,5,'#43354b');
    const offset=camera*.15;for(let i=-1;i<12;i++){const x=i*56-(offset%56);const h=38+((i*37+91)%55);rect(x,148-h,42,h,s.far);for(let wy=154-h;wy<143;wy+=12)for(let wx=x+7;wx<x+38;wx+=12)if(((wx+wy+i)%3)!==0)rect(wx,wy,4,5,s.accent+'88');rect(x+4,146-h,4,h,'#ffffff0d');}
    const o2=camera*.35;for(let i=-1;i<10;i++){const x=i*72-(o2%72);const h=25+((i*29+17)%40);rect(x,160-h,56,h,s.near);rect(x+5,158-h,46,3,'#ffffff12');for(let wx=x+9;wx<x+51;wx+=14)rect(wx,168-h,5,7,'#e6986388');}
    // power lines and city lamps
    for(let i=0;i<6;i++){const x=i*110-(camera*.52%110);rect(x,136,2,30,'#171a25');rect(x-9,137,19,2,'#171a25');rect(x+2,138,2,20,'#514252');}
  }
  function drawGround(){rect(0,GROUND,W,H-GROUND,'#171923');rect(0,GROUND,W,3,stages[stage].accent);for(let x=-(camera%24);x<W;x+=24){rect(x,GROUND+8,13,2,'#30313c');rect(x+4,GROUND+18,5,2,'#252732');}for(let i=0;i<4;i++){const x=((i*147-camera*.7)%520+520)%520;rect(x,GROUND-7,2,7,'#ffb56d');rect(x-2,GROUND-9,6,2,'#ffb56d');}}
  function drawPlatforms(){for(const p of platforms[stage]){const x=p.x-camera;if(x<-110||x>W+30)continue;rect(x,p.y,p.w,5,'#bc715c');rect(x,p.y+5,p.w,5,'#47404a');for(let px=x+5;px<x+p.w;px+=14){rect(px,p.y+10,8,7,'#302d39');rect(px+2,p.y+17,4,4,'#1d202a');}}}
  function drawPlayer(){if(!player)return;const x=Math.round(player.x-camera),y=Math.round(player.y);if(player.invuln>0&&Math.floor(time*18)%2===0)return;const run=Math.abs(player.vx)>.45?Math.sin(player.anim)*2:0;
    // trailing jacket/scarf
