    if(player.attack>0){const reach=player.power>0?22:14;rect(x+8+player.face*9,y+15,reach,3,player.power>0?'#d58bff':'#fff0c1');rect(x+8+player.face*17,y+12,3,8,player.power>0?'#d58bff':'#ffb56d');}
