    const heartLabels=['HUMAN','SYMBIOTE','WOLF'];for(let i=0;i<3;i++){const x=183+i*25;text(i===0?'♥':i===1?'✦':'◆',x,20,10,i===0?'#ff5362':i===1&&stage>0?'#bb6ee6':i===2&&stage>1?'#ffc565':'#4c4a58');}
